package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbNativeBNodeExpressionTest {

	private static final String EX = "urn:bnode:";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String QUERY = "SELECT ?s ?same1 ?same2 ?sameCall ?fresh1 ?fresh2 WHERE { "
			+ "?s <urn:bnode:p> ?o . "
			+ "BIND(BNODE(\"label\") AS ?same1) "
			+ "BIND(?same1 AS ?same2) "
			+ "BIND(sameTerm(BNODE(\"inner\"), BNODE(\"inner\")) AS ?sameCall) "
			+ "BIND(BNODE() AS ?fresh1) "
			+ "BIND(BNODE() AS ?fresh2) }";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI predicate = vf.createIRI(EX, "p");
			connection.add(vf.createIRI(EX, "s1"), predicate, vf.createLiteral(1));
			connection.add(vf.createIRI(EX, "s2"), predicate, vf.createLiteral(2));
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void labeledIdentityAndUnlabeledFreshnessStayNativePerLogicalSolution() {
		List<BindingSet> generic = rows(false);
		assertIdentityInvariants(generic);

		long islandsBefore = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
		long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		List<BindingSet> nativeRows = rows(true);
		assertIdentityInvariants(nativeRows);
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get()).isEqualTo(islandsBefore);
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get()).isEqualTo(hostedBefore);
	}

	@Test
	void labeledIdentityIsFreshAcrossEvaluations() {
		Set<Value> first = values(rows(true), "same1");
		Set<Value> second = values(rows(true), "same1");
		assertThat(first).hasSize(2);
		assertThat(second).hasSize(2);
		assertThat(first).doesNotContainAnyElementsOf(second);
	}

	@Test
	void distinctLabeledBNodeCountsLogicalSolutionsNatively() {
		String query = "SELECT (COUNT(DISTINCT ?b) AS ?count) WHERE { "
				+ "?s <urn:bnode:p> ?o . BIND(BNODE(\"label\") AS ?b) }";
		long islandsBefore = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
		List<BindingSet> nativeRows = rows(query, true);
		assertThat(nativeRows).singleElement()
				.extracting(row -> row.getValue("count").stringValue())
				.isEqualTo("2");
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get()).isEqualTo(islandsBefore);
	}

	private void assertIdentityInvariants(List<BindingSet> rows) {
		assertThat(rows).hasSize(2);
		for (BindingSet row : rows) {
			Value same1 = row.getValue("same1");
			Value same2 = row.getValue("same2");
			Value fresh1 = row.getValue("fresh1");
			Value fresh2 = row.getValue("fresh2");
			assertThat(same1).isInstanceOf(BNode.class).isEqualTo(same2);
			assertThat(row.getValue("sameCall").stringValue()).isEqualTo("true");
			assertThat(fresh1).isInstanceOf(BNode.class).isNotEqualTo(fresh2).isNotEqualTo(same1);
		}
		assertThat(rows.get(0).getValue("same1")).isNotEqualTo(rows.get(1).getValue("same1"));
	}

	private List<BindingSet> rows(boolean nativeEnabled) {
		return rows(QUERY, nativeEnabled);
	}

	private Set<Value> values(List<BindingSet> rows, String name) {
		Set<Value> values = new HashSet<>();
		for (BindingSet row : rows) {
			values.add(row.getValue(name));
		}
		return values;
	}

	private List<BindingSet> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}
}
